declare module "ipaddr.js" {
    type IPvXRangeDefaults = 'unicast' | 'unspecified' | 'multicast' | 'linkLocal' | 'loopback' | 'reserved' | 'benchmarking' | 'amt';
    type IPvRange = IPvXRangeDefaults | 'broadcast' | 'carrierGradeNat' | 'private' | 'as';
    type IPvRange = IPvXRangeDefaults | 'uniqueLocal' | 'ipvMapped' | 'rfc' | 'rfc' | 'to' | 'teredo' | 'asv' | 'orchid' | 'droneRemoteIdProtocolEntityTags';

    interface RangeList<T> {
        [name: string]: [T, number] | [T, number][];
    }

    // Common methods/properties for IPv and IPv classes.
    class IP {
        prefixLengthFromSubnetMask(): number | null;
        toByteArray(): number[];
        toNormalizedString(): string;
        toString(): string;
    }

    namespace Address {
        export function fromByteArray(bytes: number[]): IPv | IPv;
        export function isValid(addr: string): boolean;
        export function isValidCIDR(addr: string): boolean;
        export function parse(addr: string): IPv | IPv;
        export function parseCIDR(mask: string): [IPv | IPv, number];
        export function process(addr: string): IPv | IPv;
        export function subnetMatch(addr: IPv | IPv, rangeList: RangeList<IPv | IPv>, defaultName?: string): string;

        export class IPv extends IP {
            static broadcastAddressFromCIDR(addr: string): IPv;
            static isIPv(addr: string): boolean;
            static isValid(addr: string): boolean;
            static isValidCIDR(addr: string): boolean;
            static isValidFourPartDecimal(addr: string): boolean;
            static isValidCIDRFourPartDecimal(addr: string): boolean;
            static networkAddressFromCIDR(addr: string): IPv;
            static parse(addr: string): IPv;
            static parseCIDR(addr: string): [IPv, number];
            static subnetMaskFromPrefixLength(prefix: number): IPv;
            constructor(octets: number[]);
            octets: number[]

            kind(): 'ipv';
            match(what: IPv | IPv | [IPv | IPv, number], bits?: number): boolean;
            range(): IPvRange;
            subnetMatch(rangeList: RangeList<IPv>, defaultName?: string): string;
            toIPvMappedAddress(): IPv;
        }

        export class IPv extends IP {
            static broadcastAddressFromCIDR(addr: string): IPv;
            static isIPv(addr: string): boolean;
            static isValid(addr: string): boolean;
            static isValidCIDR(addr: string): boolean;
            static networkAddressFromCIDR(addr: string): IPv;
            static parse(addr: string): IPv;
            static parseCIDR(addr: string): [IPv, number];
            static subnetMaskFromPrefixLength(prefix: number): IPv;
            constructor(parts: number[]);
            parts: number[]
            zoneId?: string

            isIPvMappedAddress(): boolean;
            kind(): 'ipv';
            match(what: IPv | IPv | [IPv | IPv, number], bits?: number): boolean;
            range(): IPvRange;
            subnetMatch(rangeList: RangeList<IPv>, defaultName?: string): string;
            toIPvAddress(): IPv;
            toRFCString(): string;
        }
    }

    export = Address;
}
